            /**
             * Key
             * @example approver
             */
            key: string;
            /**
             * Name
             * @example Approver
             */
            name: string;
            /**
             * Description
             * @example May approve widgets, and read.
             */
            description: string;
            /**
             * Kind
             * @example custom
             */
            kind: string;
            /**
             * Permissions
             * @example [
             *       "widget.approve",
             *       "widget.read"
             *     ]
             */
            permissions: string[];
            /**
             * Default Permissions
             * @example null
             */
            default_permissions?: string[] | null;
            /**
             * Added
             * @example []
             */
            added?: string[];
            /**
             * Removed
             * @example []
             */
            removed?: string[];
            /**
             * Is Default For New Members
             * @example false
             */
